CREATE COLUMN TABLE "TEST_AP"."OSHP" ("TrnspCode" SMALLINT CS_INT NOT NULL , "TrnspName" NVARCHAR(40) NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "WebSite" NVARCHAR(50), PRIMARY KEY ("TrnspCode")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OSHP_NAME" ON "TEST_AP"."OSHP" ( "TrnspName" ASC )